-- Warrior RP original speech and emote catalog (enUS)
local _, addon = ...
addon.localeData.enUS.texts = {
    HEROIC_STRIKE = { name = "Heroic Strike", ziel = { "%s, look me in the eye: This blow carries more resolve than anger.", "*turns toward %s and launches a deliberate attack.*" }, gruppe = { "This blow carries more resolve than anger.", "The strike lands when posture and resolve meet.", "*draws back the arm and drives the weapon forward with full force.*" } },
    CHARGE = { name = "Charge", ziel = { "%s, look me in the eye: Only the distance of a breath remains between us.", "*turns toward %s and launches a deliberate attack.*" }, gruppe = { "Only the distance of a breath remains between us.", "*shifts weight forward and launches into motion.*", "Hesitation yields the field to an enemy.", "*finds the opening between two hurried movements.*", "The shortest way to the foe runs straight through fear.", "*pushes off hard and closes the distance at a run.*" } },
    REND = { name = "Rend", ziel = { "%s, look me in the eye: An open guard has consequences beyond a single moment.", "*turns toward %s and launches a deliberate attack.*" }, gruppe = { "An open guard has consequences beyond a single moment.", "A shallow wound can end grand plans.", "*draws the blade through the guard with a short, cutting motion.*" } },
    HAMSTRING = { name = "Hamstring", ziel = { "%s, look me in the eye: There is no need to hurry once the foe cannot.", "*turns toward %s and launches a deliberate attack.*" }, gruppe = { "There is no need to hurry once the foe cannot.", "A fight grows easier when the enemy's legs grow slower.", "*delivers a low, controlled slash beneath the guard.*" } },
    THUNDER_CLAP = { name = "Thunder Clap", ziel = {  }, gruppe = { "The ground itself answers my step.", "Hear that rumble? It was only the beginning.", "*stomps hard, sending a shock through the ground around them.*" } },
    CLEAVE = { name = "Cleave", ziel = {  }, gruppe = { "One sweep opens more than one path for the blade.", "Two enemies, one swing. Footwork makes the difference.", "*swings the weapon through a wide, level arc.*" } },
    EXECUTE = { name = "Execute", ziel = { "%s, look me in the eye: Now it is timing, not fury, that decides.", "*turns toward %s and launches a deliberate attack.*" }, gruppe = { "Now it is timing, not fury, that decides.", "The final blow requires the steadiest hand.", "*waits for a tiny opening and delivers the decisive strike.*" } },
    SUNDER_ARMOR = { name = "Sunder Armor", ziel = { "%s, look me in the eye: Every suit of armour has somewhere it yields.", "*turns toward %s and launches a deliberate attack.*" }, gruppe = { "Every suit of armour has somewhere it yields.", "No armour lasts forever when you know its seams.", "*strikes at the weaker joins of the armour in quick succession.*" } },
    SHIELD_BLOCK = { name = "Shield Block", ziel = {  }, gruppe = { "My shield stands where the next strike intends to land.", "The enemy may raise a weapon. My shield is already waiting.", "*catches the incoming blow on the shield's rim.*" } },
    SHIELD_BASH = { name = "Shield Bash", ziel = { "%s, look me in the eye: A blade is not required to silence a spell.", "*turns toward %s and launches a deliberate attack.*" }, gruppe = { "A blade is not required to silence a spell.", "An interrupted incantation is remarkably short.", "*drives the shield forward, breaking the foe's concentration.*" } },
    TAUNT = { name = "Taunt", ziel = { "%s, look me in the eye: Look at me. The others are not your concern.", "*turns toward %s and launches a deliberate attack.*" }, gruppe = { "Look at me. The others are not your concern.", "Here I stand. Do you truly think you can pass me?", "*rattles the shield rim and openly challenges the foe.*" } },
    BATTLE_SHOUT = { name = "Battle Shout", ziel = {  }, gruppe = { "Hold the line! Not one step back.", "Heads high! Courage carries farther than any banner.", "*raises the weapon high and rallies the companions.*" } },
    DEMORALIZING_SHOUT = { name = "Demoralizing Shout", ziel = {  }, gruppe = { "Listen carefully: your confidence ends here.", "Your ranks are shaking before I even reach them.", "*lets out a deep, cutting battle cry.*" } },
    REVENGE = { name = "Revenge", ziel = { "%s, look me in the eye: Those who test my shield receive their answer at once.", "*turns toward %s and launches a deliberate attack.*" }, gruppe = { "Those who test my shield receive their answer at once.", "Your last strike handed me an opportunity.", "*turns the enemy's weapon aside and counters at once.*" } },
    OVERPOWER = { name = "Overpower", ziel = { "%s, look me in the eye: A flaw in the guard is an invitation.", "*turns toward %s and launches a deliberate attack.*" }, gruppe = { "A flaw in the guard is an invitation.", "One step too far. The opening is mine now.", "*seizes the opening in an unbalanced guard for a swift counter.*" } },
    MORTAL_STRIKE = { name = "Mortal Strike", ziel = { "%s, look me in the eye: I put everything into one precise, heavy strike.", "*turns toward %s and launches a deliberate attack.*" }, gruppe = { "I put everything into one precise, heavy strike.", "That blow is no accident, but the end of a decision.", "*guides the heavy weapon into its mark with relentless precision.*" } },
    WHIRLWIND = { name = "Whirlwind", ziel = {  }, gruppe = { "Steel and motion form a circle without a gap.", "A circle of steel leaves little room for bravado.", "*pivots on one foot and sweeps the weapon around.*" } },
    BLOODTHIRST = { name = "Bloodthirst", ziel = { "%s, look me in the eye: I keep the pressure until the guard breaks.", "*turns toward %s and launches a deliberate attack.*" }, gruppe = { "I keep the pressure until the guard breaks.", "My fury is awake, but my blade stays precise.", "*presses the attack with a fierce blow without dropping the guard.*" } },
    INTERCEPT = { name = "Intercept", ziel = { "%s, look me in the eye: No distance is safe while I can still stand.", "*turns toward %s and launches a deliberate attack.*" }, gruppe = { "No distance is safe while I can still stand.", "*shifts weight forward and launches into motion.*", "Hesitation yields the field to an enemy.", "*finds the opening between two hurried movements.*", "A fleeing step makes no safe distance.", "*bursts from the guard and cuts off the escape route.*" } },
    PUMMEL = { name = "Pummel", ziel = { "%s, look me in the eye: The next syllable of your spell will go unsaid.", "*turns toward %s and launches a deliberate attack.*" }, gruppe = { "The next syllable of your spell will go unsaid.", "A quick fist is sometimes the best answer to magic.", "*jabs at the right moment, interrupting the incantation.*" } },
    SWEEPING_STRIKES = { name = "Sweeping Strikes", ziel = {  }, gruppe = { "Every turn of the weapon serves a purpose.", "No swing should end at the first guard.", "*carries the weapon's momentum through into a second strike.*" } },
    DEATH_WISH = { name = "Death Wish", ziel = {  }, gruppe = { "I know the risk. I advance anyway.", "I see the danger plainly. It will not turn me back.", "*loosens the shield arm and levels the weapon with purpose.*" } },
    RECKLESSNESS = { name = "Recklessness", ziel = {  }, gruppe = { "For this moment, only the committed attack matters.", "Once committed, take the whole moment.", "*casts caution aside in a succession of relentless strikes.*" } },
    LAST_STAND = { name = "Last Stand", ziel = {  }, gruppe = { "As long as I breathe, this line holds.", "This is my ground. Here I remain.", "*straightens once more despite the weight of exhaustion.*" } },
    SHIELD_WALL = { name = "Shield Wall", ziel = {  }, gruppe = { "There will be no retreat behind this shield.", "One shield is good. An unbroken line is better.", "*brings the shield close and locks the guard tight.*" } },
    RETALIATION = { name = "Retaliation", ziel = {  }, gruppe = { "Every strike will find its way back.", "Every attack also opens a counterattack.", "*absorbs the movement and strikes into the opening at once.*" } },
    MOCKING_BLOW = { name = "Mocking Blow", ziel = { "%s, look me in the eye: Come closer. I am far from finished.", "*turns toward %s and launches a deliberate attack.*" }, gruppe = { "Come closer. I am far from finished.", "A touch of arrogance makes you predictable.", "*feigns a clumsy swing, drawing the foe closer.*" } },
    BERSERKER_RAGE = { name = "Berserker Rage", ziel = {  }, gruppe = { "Fear has no place here anymore.", "Fear can wait. Resolve speaks now.", "*shakes off fear with one rough breath.*" } },
    BLOODRAGE = { name = "Bloodrage", ziel = {  }, gruppe = { "I draw strength from every racing heartbeat.", "My own pain will not break my strength.", "*strikes a fist against the chest and summons fighting spirit.*" } },
    DISARM = { name = "Disarm", ziel = { "%s, look me in the eye: A weapon is worth little once it leaves the hand.", "*turns toward %s and launches a deliberate attack.*" }, gruppe = { "A weapon is worth little once it leaves the hand.", "An empty hand is the clearest answer to boasting.", "*twists the foe's weapon arm with a short lever.*" } },
    INTIMIDATING_SHOUT = { name = "Intimidating Shout", ziel = {  }, gruppe = { "Those who lose their nerve lose their formation.", "Run while your legs will still carry you!", "*lets out a shout fierce enough to cut through the battle's roar.*" } },
    CHALLENGING_SHOUT = { name = "Challenging Shout", ziel = {  }, gruppe = { "All eyes on me. This is where the decision begins.", "All of you! Here stands the foe you came to face.", "*raises the shield overhead and challenges every attacker.*" } },
    SLAM = { name = "Slam", ziel = { "%s, look me in the eye: A clean strike needs weight and patience.", "*turns toward %s and launches a deliberate attack.*" }, gruppe = { "A clean strike needs weight and patience.", "The blade does not merely fall hard. It falls true.", "*winds up and drives the weapon down with the weight of the whole body.*" } },
    DEVASTATE = { name = "Devastate", ziel = { "%s, look me in the eye: I find the weak point and give it no support.", "*turns toward %s and launches a deliberate attack.*" }, gruppe = { "I find the weak point and give it no support.", "Weak armour yields; broken armour yields faster.", "*presses the assault against an already damaged section of armour.*" } },
    SHIELD_SLAM = { name = "Shield Slam", ziel = { "%s, look me in the eye: My shield answers as readily as my weapon.", "*turns toward %s and launches a deliberate attack.*" }, gruppe = { "My shield answers as readily as my weapon.", "My shield is no decoration on my left arm.", "*drives the shield's edge forward with full force.*" } },
    CONCUSSION_BLOW = { name = "Concussion Blow", ziel = { "%s, look me in the eye: A moment's carelessness can undo an entire plan.", "*turns toward %s and launches a deliberate attack.*" }, gruppe = { "A moment's carelessness can undo an entire plan.", "A clean hit can steal a whole thought from the foe.", "*lands a heavy blow against the exposed guard.*" } },
    VICTORY_RUSH = { name = "Victory Rush", ziel = { "%s, look me in the eye: The next step belongs to the survivors.", "*turns toward %s and launches a deliberate attack.*" }, gruppe = { "The next step belongs to the survivors.", "One victory lends strength for the next step.", "*straightens after the victory and presses onward.*" } },
    BATTLE_STANCE = { name = "Battle Stance", ziel = {  }, gruppe = { "*shifts weight and settles into a balanced fighting stance.*", "Good footing leaves room for every next move.", "*judges the distance and keeps the weapon ready.*", "A warrior does not lose balance just because battle begins.", "I hold the centre and leave every path open.", "*settles into a balanced stance, ready to strike or counter.*" } },
    DEFENSIVE_STANCE = { name = "Defensive Stance", ziel = {  }, gruppe = { "*brings the shield close and closes every opening in the guard.*", "This line will hold behind my shield.", "*plants both feet and prepares to weather the first blow.*", "Anyone who wants my allies must get past me first.", "Today the shield matters more than glory.", "*lowers the centre of gravity and guards the allies with the shield.*" } },
    BERSERKER_STANCE = { name = "Berserker Stance", ziel = {  }, gruppe = { "*drops into a low stance and lets out a harsh battle cry.*", "My fury knows its target; my mind remains my own.", "*sweeps the weapon through the air with fierce purpose.*", "There is no retreat from this point.", "Fury has opened its gate. My hand will guide it.", "*adopts an aggressive stance and levels the weapon.*" } },
    PIERCING_HOWL = { name = "Piercing Howl", ziel = {  }, gruppe = { "*lets a piercing howl roll across the battlefield.*", "You won't escape so easily!", "*looses a shout that carries through steel and drums.*", "Stand your ground and face the fight!", "Even behind the ranks, they will hear my call.", "*draws a deep breath and releases a long, piercing cry.*" } },
    SPEARING_STRIKE = { name = "Spearing Strike", ziel = { "%s, even a giant must guard against a well-aimed point.", "*turns toward %s and launches a deliberate attack.*" }, gruppe = { "*drives into a powerful, straight thrust.*", "Size is no shield against a well-placed point.", "*takes careful aim and puts the whole body's strength into the thrust.*", "A clean thrust takes resolve, not haste.", "The point finds its way where the armour yields.", "*channels the whole body's momentum into a focused thrust.*" } },
    TACTICAL_MASTERY = { name = "Tactical Mastery", ziel = {  }, gruppe = { "*changes stance without losing the rhythm of battle.*", "A new stance, the same iron will.", "*adjusts the footing while holding on to combat readiness.*", "A clever warrior wastes neither steps nor strength.", "One step aside can achieve more than ten wild blows.", "*shifts stance without losing sight of the surrounding foes.*" } },
}
